static rt_err_t aicmac_rt_control(rt_device_t dev, int cmd, void *args)
{
    aicmac_rt_t *mac = dev->user_data;
    switch (cmd)
    {
        case NIOCTL_GADDR:

            /* get mac address */
            if (args) rt_memcpy(args, mac->dev_addr, 6);
            else return -RT_ERROR;

            break;

        default :
