        hal_clk_set_freq(id, 50000000);
        /* clock enable & reset deassert */
        hal_clk_enable_deassertrst_iter(id);
    } else {
        /* clock enable & reset deassert */
        hal_clk_disable_assertrst(id);
    }
}

