    u16 lpa, lpagb, adv;
    int err = 0;

    if (phydev->autoneg) {
        if (!phydev->autoneg_complete) {
            mii_stat1000_mod_linkmode_lpa_t(phydev->lp_advertising, 0);
            mii_lpa_mod_linkmode_lpa_t(phydev->lp_advertising, 0);
            return 0;
