+  aicmac_set_dma_tx(port, DISABLE);
+  aicmac_set_dma_rx(port, DISABLE);
+  aicmac_set_mac_rx(port, DISABLE);
+  aicmac_flush_tx_fifo(port);
+  aicmac_set_mac_tx(port, DISABLE);
