+  if (state)
+    {
+      tmpreg |= ETH_FLOWCTL_RFE | ETH_FLOWCTL_TFE;
+    }
+  else
+    {
+      tmpreg &= ~(ETH_FLOWCTL_RFE | ETH_FLOWCTL_TFE);
