+
+void aicmac_set_mac_rx(uint32_t port, bool state)
+{
+  uint32_t tmpreg = readl(MAC(port, macrxfunc));
+
+  if (state)
+    {
+      tmpreg |= ETH_MACRXFUNC_RE;
+    }
+  else
