+
+  tmpreg = ((uint32_t)addr[5] << 8) | (uint32_t)addr[4];
+  writel(tmpreg, MAC(port, macaddr0high) + index * 8);
+
+  tmpreg = ((uint32_t)addr[3] << 24) | ((uint32_t)addr[2] << 16) |
+           ((uint32_t)addr[1] << 8) | addr[0];
+  writel(tmpreg, MAC(port, macaddr0low) + index * 8);
