+static bool aic_eth_parse_mac(const char *str, uint8_t mac[6])
+{
+  uint8_t tmp[6];
+  int count = 0;
+
+  if (str == NULL)
+    {
+      return false;
+    }
+
+  while (*str != '\0' && count < 6)
+    {
+      int hi;
+      int lo;
+
+      while (*str == ':' || *str == '-' || *str == ' ')
+        {
+          str++;
+        }
+
+      hi = aic_eth_hexval(str[0]);
+      lo = aic_eth_hexval(str[1]);
+      if (hi < 0 || lo < 0)
+        {
+          return false;
+        }
+
+      tmp[count++] = (uint8_t)((hi << 4) | lo);
+      str += 2;
+
+      if (*str == ':' || *str == '-' || *str == ' ')
+        {
+          str++;
+        }
+    }
+
+  if (count != 6)
+    {
+      return false;
+    }
+
+  memcpy(mac, tmp, 6);
+  return true;
