   133	  if (ret)
   134	    {
   135	      return ETH_ERROR;
   136	    }
   137	
   138	  phydev->duplex = (bmcr & BMCR_FULLDPLX) ? DUPLEX_FULL : DUPLEX_HALF;
   139	  phydev->speed = (bmcr & BMCR_SPEED100) ? SPEED_100 : SPEED_10;
   140	  phydev->pause = 0;
   141	  phydev->asym_pause = 0;
   142	  return ETH_SUCCESS;
   143	}
   144	
   145	static int aicphy_resolve_aneg(uint32_t port)
   146	{
   147	  aic_phy_device_t *phydev = &phy_device[port];
   148	  uint16_t adv;
   149	  uint16_t lpa;
   150	  uint16_t common;
   151	  int ret;
   152	
   153	  ret = aicmac_read_phy_reg(port, MII_ADVERTISE, &adv);
   154	  if (ret)
   155	    {
   156	      return ETH_ERROR;
   157	    }
   158	
   159	  ret = aicmac_read_phy_reg(port, MII_LPA, &lpa);
   160	  if (ret)
   161	    {
   162	      return ETH_ERROR;
   163	    }
   164	
   165	  common = adv & lpa;
   166	
   167	  if (common & LPA_100FULL)
   168	    {
   169	      phydev->speed = SPEED_100;
   170	      phydev->duplex = DUPLEX_FULL;
   171	    }
   172	  else if (common & LPA_100HALF)
   173	    {
   174	      phydev->speed = SPEED_100;
   175	      phydev->duplex = DUPLEX_HALF;
   176	    }
   177	  else if (common & LPA_10FULL)
   178	    {
   179	      phydev->speed = SPEED_10;
   180	      phydev->duplex = DUPLEX_FULL;
   181	    }
   182	  else
   183	    {
   184	      phydev->speed = SPEED_10;
   185	      phydev->duplex = DUPLEX_HALF;
   186	    }
   187	
   188	  phydev->pause = (common & LPA_PAUSE_CAP) ? 1 : 0;
   189	  phydev->asym_pause = 0;
   190	  return ETH_SUCCESS;
   191	}
