   211	          return ETH_ERROR;
   212	        }
   213	    }
   214	
   215	  phydev->link = (bmsr & BMSR_LSTATUS) ? 1 : 0;
   216	  phydev->autoneg_complete = (bmsr & BMSR_ANEGCOMPLETE) ? 1 : 0;
   217	
   218	  if (phydev->autoneg && !phydev->autoneg_complete)
   219	    {
   220	      phydev->link = 0;
   221	    }
   222	
   223	  if (!phydev->link)
   224	    {
   225	      phydev->speed = SPEED_UNKNOWN;
   226	      phydev->duplex = DUPLEX_UNKNOWN;
   227	      phydev->pause = 0;
   228	      phydev->asym_pause = 0;
   229	      return ETH_SUCCESS;
   230	    }
   231	
   232	  if (phydev->autoneg && phydev->autoneg_complete)
   233	    {
   234	      return aicphy_resolve_aneg(port);
   235	    }
   236	
   237	  return aicphy_read_fixed(port);
   238	}
