    74	    int old_link = 0;
    75	    int err;
    76	
    77	    while(1) {
    78	        /* Sleep */
    79	        aicos_msleep(2000);
    80	
    81	        /* Pool phy satus */
    82	        err = aicphy_read_status(port);
    83	        if (err) {
    84	            pr_err("%s fail.\n", __func__);
    85	            continue;
    86	        }
    87	
    88	        /* Phy link status not change */
    89	        if (old_link == phydev->link)
    90	            continue;
    91	        old_link = phydev->link;
    92	
    93	        /* Phy link status change: DOWN -> UP */
    94	        if (phydev->link) {
    95	            pr_info(" Port %d link UP! %s mode: speed %dM, %s duplex, flow control %s.\n",
