   105	                aicmac_set_mac_duplex(port, phydev->duplex);
   106	                aicmac_set_mac_pause(port, phydev->pause);
   107	            }
   108	
   109	            /* Enable MAC and DMA transmission and reception */
   110	            aicmac_start(port);
   111	
   112	            eth_device_linkchange(&mac->parent, RT_TRUE);
   113	        /* Phy link status change: UP -> DOWN */
   114	        } else {
