      aicmac_start(priv->port);
      netdev_lower_carrier_on(&priv->lower);
      syslog(LOG_INFO,
             "GMAC%u link UP: %dM %s duplex flowctl %s\n",
             (unsigned int)priv->port, phydev->speed,
             phydev->duplex == DUPLEX_FULL ? "full" : "half",
             phydev->pause ? "on" : "off");
    }
